import React from 'react';

const TABS = [
  { id:'home',      icon:'◎', label:'Hem' },
  { id:'checkin',   icon:'◈', label:'Check-in' },
  { id:'history',   icon:'◫', label:'Historik' },
  { id:'breathing', icon:'◯', label:'Andning' },
];

export default function Nav({ page, setPage }) {
  return (
    <>
      {/* Top bar — just the brand */}
      <div style={{ position:'fixed', top:0, left:0, right:0, zIndex:100, display:'flex', alignItems:'center', justifyContent:'space-between', padding:'0 24px', height:56, background:'rgba(12,12,14,0.85)', backdropFilter:'blur(20px)', borderBottom:'1px solid rgba(255,255,255,0.05)' }}>
        <div style={{ display:'flex', alignItems:'center', gap:10 }}>
          <div style={{ fontFamily:'DM Mono,monospace', fontSize:11, letterSpacing:'0.2em', color:'rgba(242,240,235,0.4)', textTransform:'uppercase' }}>Mental Health</div>
          <span style={{ color:'rgba(255,255,255,0.15)', fontSize:10 }}>·</span>
          <div style={{ fontFamily:'DM Mono,monospace', fontSize:11, letterSpacing:'0.2em', color:'rgba(242,240,235,0.4)', textTransform:'uppercase' }}>KBT</div>
        </div>
        <div style={{ fontSize:18, fontWeight:900, letterSpacing:'-0.04em', color:'#f2f0eb' }}>SPIRAL</div>
      </div>

      {/* Bottom tab bar */}
      <div style={{ position:'fixed', bottom:0, left:0, right:0, zIndex:100, display:'flex', alignItems:'stretch', height:64, background:'rgba(12,12,14,0.95)', backdropFilter:'blur(24px)', borderTop:'1px solid rgba(255,255,255,0.06)' }}>
        {TABS.map(tab => (
          <button key={tab.id} onClick={()=>setPage(tab.id)}
            style={{ flex:1, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', gap:3, transition:'all .2s', background:'none', border:'none', borderTop:`2px solid ${page===tab.id?'rgba(242,240,235,0.7)':'transparent'}` }}>
            <span style={{ fontSize:16, color: page===tab.id ? '#f2f0eb' : 'rgba(242,240,235,0.28)', transition:'all .2s', transform: page===tab.id ? 'scale(1.15)' : 'scale(1)' }}>{tab.icon}</span>
            <span style={{ fontFamily:'DM Mono,monospace', fontSize:8, letterSpacing:'0.12em', textTransform:'uppercase', color: page===tab.id ? 'rgba(242,240,235,0.7)' : 'rgba(242,240,235,0.22)' }}>{tab.label}</span>
          </button>
        ))}
      </div>
    </>
  );
}
